package dev.zomboid.isotacz;
import java.util.*;import java.util.function.Predicate;
public final class VehicleView {
 static Object seat(){try{Object wrapper=R.call(R.get(R.type("minecrafttransportsimulator.mcinterface.InterfaceManager"),"clientInterface"),"getClientPlayer");return wrapper==null?null:R.call(wrapper,"getEntityRiding");}catch(IllegalStateException missing){Throwable root=missing;while(root.getCause()!=null)root=root.getCause();if(root instanceof ClassNotFoundException)return null;throw missing;}}
 public static boolean builder(Object entity){return entity!=null&&entity.getClass().getName().startsWith("mcinterface1211.BuilderEntity");}
 public static void visible(Object entity){if(!builder(entity))return;for(String method:new String[]{"setCulled","setOutOfCamera"})try{R.call(entity,method,false);}catch(IllegalStateException missing){Throwable root=missing;while(root.getCause()!=null)root=root.getCause();if(!(root instanceof NoSuchMethodException))throw missing;}try{R.call(entity,"setForcedVisible",true);}catch(IllegalStateException missing){Throwable root=missing;while(root.getCause()!=null)root=root.getCause();if(!(root instanceof NoSuchMethodException))throw missing;}}
 public static void keepVisible(){Object mc=Bridge.mc(),player=R.get(mc,"player"),level=R.get(mc,"level");if(!Bridge.active()||player==null||level==null)return;Object box=R.call(R.call(player,"getBoundingBox"),"inflate",96d);Predicate<Object> filter=VehicleView::builder;for(Object entity:(List<?>)R.call(level,"getEntities",player,box,filter))visible(entity);}
 public static void nativeTick(){Object mc=Bridge.mc();if(!Bridge.active()||R.get(mc,"player")==null||R.get(mc,"level")==null)return;R.call(R.type("com.cleannrooster.dungeons_iso.compat.SodiumCompat"),"run");}
 public static Object focus(Object original){if(!Bridge.active())return original;Object seat=seat();if(seat==null)return original;Object vehicle=R.get(seat,"vehicleOn");if(vehicle==null)return original;Object box=R.get(vehicle,"encompassingBox"),center=R.get(box,"globalCenter");double x=R.num(R.get(center,"x")),y=R.num(R.get(center,"y")),z=R.num(R.get(center,"z")),rx=R.num(R.get(box,"widthRadius")),ry=R.num(R.get(box,"heightRadius")),rz=R.num(R.get(box,"depthRadius"));double floor=R.num(R.get(R.get(vehicle,"position"),"y"));double minY=Math.max(R.num(R.get(original,"minY")),Math.floor(floor)+1);double maxY=Math.max(minY+.5,y+ry+.3);return R.make("net.minecraft.world.phys.AABB",x-rx-.3,minY,z-rz-.3,x+rx+.3,maxY,z+rz+.3);}
}
